import struct
import hashlib
import hmac
import os
import time
import secrets
from typing import Optional, Tuple, Dict

# Secure token-based session management system
# Protocol: [version:1][timestamp:8][user_id:4][payload_len:2][payload:N][signature:32]

SECRET_KEY = os.environ.get('SESSION_SECRET', secrets.token_hex(32)).encode()
MAX_PAYLOAD_SIZE = 4096
TOKEN_VERSION = 0x01
SESSION_TIMEOUT = 3600  # 1 hour


class SessionStore:
    """Thread-safe in-memory session store with automatic expiry."""

    def __init__(self):
        self._sessions: Dict[int, dict] = {}
        self._revoked: set = set()

    def create_session(self, user_id: int, role: str = 'user') -> dict:
        session = {
            'user_id': user_id,
            'role': role,
            'created_at': time.time(),
            'permissions': self._default_permissions(role)
        }
        self._sessions[user_id] = session
        return session

    def get_session(self, user_id: int) -> Optional[dict]:
        return self._sessions.get(user_id)

    def revoke(self, token_hash: str):
        self._revoked.add(token_hash)

    def is_revoked(self, token_hash: str) -> bool:
        return token_hash in self._revoked

    def _default_permissions(self, role: str) -> list:
        if role == 'admin':
            return ['read', 'write', 'delete', 'admin']
        return ['read']


class TokenParser:
    """Binary token parser with integrity verification."""

    HEADER_SIZE = 1 + 8 + 4 + 2  # version + timestamp + user_id + payload_len
    SIGNATURE_SIZE = 32

    def __init__(self, secret: bytes):
        self._secret = secret

    def create_token(self, user_id: int, payload: bytes) -> bytes:
        """Create a signed session token."""
        if len(payload) > MAX_PAYLOAD_SIZE:
            raise ValueError("Payload too large")

        timestamp = int(time.time())
        header = struct.pack('>BqIH', TOKEN_VERSION, timestamp, user_id, len(payload))
        token_body = header + payload
        signature = self._compute_signature(token_body)
        return token_body + signature

    def parse_token(self, raw_token: bytes) -> Optional[Tuple[int, int, bytes]]:
        """Parse and validate a session token.

        Returns (user_id, timestamp, payload) or None if invalid.
        Performs bounds checking on all fields.
        """
        if not raw_token or len(raw_token) < self.HEADER_SIZE + self.SIGNATURE_SIZE:
            return None

        # Extract header fields
        version = raw_token[0]
        if version != TOKEN_VERSION:
            return None

        timestamp = struct.unpack('>q', raw_token[1:9])[0]
        user_id = struct.unpack('>I', raw_token[9:13])[0]
        payload_len = struct.unpack('>H', raw_token[13:15])[0]  # unsigned short

        # Validate payload length bounds
        if payload_len > MAX_PAYLOAD_SIZE:
            return None

        # Calculate expected total token size
        expected_size = self.HEADER_SIZE + payload_len + self.SIGNATURE_SIZE
        if len(raw_token) != expected_size:
            return None

        # Verify signature over header + payload
        token_body = raw_token[:self.HEADER_SIZE + payload_len]
        provided_sig = raw_token[self.HEADER_SIZE + payload_len:]

        expected_sig = self._compute_signature(token_body)
        if not secrets.compare_digest(provided_sig, expected_sig):
            return None

        # Check timestamp validity
        current_time = int(time.time())
        if current_time - timestamp > SESSION_TIMEOUT:
            return None

        payload = raw_token[self.HEADER_SIZE:self.HEADER_SIZE + payload_len]
        return (user_id, timestamp, payload)

    def _compute_signature(self, data: bytes) -> bytes:
        """HMAC-SHA256 signature computation."""
        return hmac.new(self._secret, data, hashlib.sha256).digest()


class AuthMiddleware:
    """Request authentication middleware."""

    def __init__(self):
        self._parser = TokenParser(SECRET_KEY)
        self._store = SessionStore()

    def authenticate(self, raw_token: bytes) -> Optional[dict]:
        """Authenticate a request using the provided token.

        Returns session dict if valid, None otherwise.
        """
        # Check revocation by token hash
        token_hash = hashlib.sha256(raw_token).hexdigest()
        if self._store.is_revoked(token_hash):
            return None

        result = self._parser.parse_token(raw_token)
        if result is None:
            return None

        user_id, timestamp, payload = result

        # Retrieve session from store
        session = self._store.get_session(user_id)
        if session is None:
            return None

        return session

    def create_authenticated_session(self, user_id: int, role: str = 'user') -> bytes:
        """Create a new session and return the token."""
        session = self._store.create_session(user_id, role)
        payload = role.encode('utf-8')
        return self._parser.create_token(user_id, payload)

    def check_permission(self, session: dict, required: str) -> bool:
        """Check if session has required permission."""
        return required in session.get('permissions', [])
